112	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
113	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
114	        if (normalizedTelephone == null) {
115	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
116	        }
117	        String normalizedAddress = Owner.normalizeAddress(ownerFieldsDto.getAddress());
118	        if (normalizedAddress == null || normalizedAddress.isBlank()) {
119	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
120	        }
121	        if (!this.clinicService.findOwnerByTelephone(normalizedTelephone).isEmpty()) {
122	            return new ResponseEntity<>(HttpStatus.CONFLICT);
123	        }
124	        if (countOwnersInCity(ownerFieldsDto.getCity()) >= 50) {
125	            return new ResponseEntity<>(HttpStatus.CONFLICT);
126	        }
127	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
128	        LocalDate effectiveDate =
129	            owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
130	        LocalDate registrationDate = toBusinessDay(effectiveDate);
131	        long ownersRegisteredToday = countOwnersRegisteredOn(registrationDate);
132	        if (ownersRegisteredToday >= 100) {
133	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
134	        }
135	        boolean bulkSignupWarning = ownersRegisteredToday > 80;
136	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
137	        List<Owner> householdMembers =
138	            findHouseholdMembers(ownerFieldsDto.getLastName(), normalizedAddress);
139	        if (!sharesHousehold && !householdMembers.isEmpty()) {
140	            return new ResponseEntity<>(HttpStatus.CONFLICT);
