146	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
147	        owner.setBulkSignupWarning(bulkSignupWarning);
148	        if (sharesHousehold && !householdMembers.isEmpty()) {
149	            String householdId = householdId(owner.getLastName(), normalizedAddress);
150	            owner.setHouseholdId(householdId);
151	            owner.setHouseholdSize(householdMembers.size() + 1);
152	            for (Owner member : householdMembers) {
153	                if (member.getHouseholdId() == null || member.getHouseholdId().isBlank()) {
154	                    member.setHouseholdId(householdId);
155	                    this.clinicService.saveOwner(member);
156	                }
157	            }
158	        }
159	        this.clinicService.saveOwner(owner);
160	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
161	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
162	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
163	        headers.setLocation(UriComponentsBuilder.newInstance()
164	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
165	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
166	    }
