252	
253	    /**
254	     * Normalize a telephone number to E.164 form. Spaces, dashes and brackets are
255	     * stripped. When a leading {@code '+'} and country code are present they are kept;
256	     * otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
257	     * is dropped from the national digits. The result must be a {@code '+'} followed
258	     * by 8 to 15 digits, and is returned as {@code +<digits>}; otherwise {@code null}
259	     * is returned to signal a bad request.
260	     */
261	    /**
262	     * Build the customer code for a newly created owner, formatted
263	     * {@code '<CITY3>-<LAST3>-<NNNN>'} where {@code CITY3} is the upper-cased first
264	     * three letters of the city, {@code LAST3} the upper-cased first three letters of
265	     * the last name, and {@code NNNN} a per-city 4-digit zero-padded sequence equal to
266	     * one more than the number of owners already in that city.
267	     */
268	    private String nextCustomerCode(String city, String lastName) {
269	        String cityPrefix = prefixThree(city);
270	        String lastNamePrefix = prefixThree(lastName);
271	        String normalizedCity = normalizeForHousehold(city);
272	        int sequence = (int) this.clinicService.findAllOwners().stream()
273	            .filter(existing -> normalizeForHousehold(existing.getCity()).equals(normalizedCity))
274	            .count() + 1;
275	        return String.format("%s-%s-%04d", cityPrefix, lastNamePrefix, sequence);
276	    }
277	
278	    /**
279	     * Count the existing owners whose city matches the given one, compared after
280	     * collapsing whitespace and lower-casing. Used to enforce the per-city capacity
281	     * cap: a city that already holds this many owners is at capacity.
282	     */
283	    private long countOwnersInCity(String city) {
284	        String normalizedCity = normalizeForHousehold(city);
285	        return this.clinicService.findAllOwners().stream()
286	            .filter(existing -> normalizeForHousehold(existing.getCity()).equals(normalizedCity))
287	            .count();
288	    }
289	
290	    /**
291	     * Count the existing owners whose registration date falls on the given day. Used to
292	     * enforce the per-day create limit: once this many owners have been registered today,
293	     * the day is at capacity and further creates are rejected.
294	     */
295	    private long countOwnersRegisteredOn(LocalDate day) {
296	        return this.clinicService.findAllOwners().stream()
297	            .filter(existing -> day.equals(existing.getRegistrationDate()))
298	            .count();
299	    }
300	
301	    /**
302	     * Roll a registration date forward to the next business day: a date falling on a
303	     * Saturday or Sunday is advanced to the following Monday, while a weekday is
304	     * returned unchanged.
305	     */
306	    private LocalDate toBusinessDay(LocalDate date) {
307	        DayOfWeek dayOfWeek = date.getDayOfWeek();
308	        if (dayOfWeek == DayOfWeek.SATURDAY || dayOfWeek == DayOfWeek.SUNDAY) {
309	            return date.plusDays(8 - dayOfWeek.getValue());
310	        }
311	        return date;
312	    }
313	
314	    /** Upper-cased first three letters of {@code value} (fewer if shorter, empty if null). */
315	    private String prefixThree(String value) {
316	        String v = value == null ? "" : value;
317	        return v.substring(0, Math.min(3, v.length())).toUpperCase(Locale.ROOT);
318	    }
319	
320	    /**
321	     * Find the existing owners that already belong to the same household as the given
322	     * last name and address, i.e. those sharing both fields. Both are compared
323	     * case-insensitively after collapsing runs of whitespace to a single space and
324	     * trimming the ends.
325	     */
326	    private List<Owner> findHouseholdMembers(String lastName, String address) {
327	        String normalizedLastName = normalizeForHousehold(lastName);
328	        String normalizedAddress = normalizeForHousehold(address);
329	        return this.clinicService.findAllOwners().stream()
330	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
331	                && normalizeForHousehold(existing.getAddress()).equals(normalizedAddress))
332	            .toList();
333	    }
334	
335	    /**
336	     * Count the existing owners that already share both the given first and last
337	     * name, compared case-insensitively. Used to populate an owner's namesake count
338	     * at creation time, reflecting how many owners with the same name existed before
339	     * this one was created.
340	     */
341	    private int countNamesakes(String firstName, String lastName) {
342	        String normalizedFirstName = normalizeName(firstName);
343	        String normalizedLastName = normalizeName(lastName);
344	        return (int) this.clinicService.findAllOwners().stream()
345	            .filter(existing -> normalizeName(existing.getFirstName()).equals(normalizedFirstName)
346	                && normalizeName(existing.getLastName()).equals(normalizedLastName))
347	            .count();
348	    }
349	
350	    private String normalizeName(String value) {
351	        return value == null ? "" : value.toLowerCase(Locale.ROOT);
352	    }
353	
354	    /**
355	     * Build a stable identifier shared by all owners of one household. It is derived
356	     * deterministically from the normalized last name and address, so every owner at
357	     * the same household resolves to the same value regardless of creation order.
358	     */
359	    private String householdId(String lastName, String address) {
360	        String key = normalizeForHousehold(lastName) + "\n" + normalizeForHousehold(address);
361	        try {
362	            byte[] digest = MessageDigest.getInstance("SHA-256")
363	                .digest(key.getBytes(StandardCharsets.UTF_8));
364	            StringBuilder sb = new StringBuilder();
365	            for (int i = 0; i < 6; i++) {
366	                sb.append(String.format("%02X", digest[i]));
367	            }
368	            return "HH-" + sb;
369	        }
370	        catch (NoSuchAlgorithmException e) {
371	            throw new IllegalStateException(e);
372	        }
373	    }
374	
375	    private String normalizeForHousehold(String value) {
376	        if (value == null) {
377	            return "";
378	        }
379	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
380	    }
381	
382	    private String normalizeTelephone(String telephone) {
383	        if (telephone == null) {
384	            return null;
385	        }
386	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
387	        String digits;
388	        if (cleaned.startsWith("+")) {
389	            digits = cleaned.substring(1);
390	        } else {
391	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
392	            digits = "61" + national;
393	        }
394	        return digits.matches("[0-9]{8,15}") ? "+" + digits : null;
395	    }
396	
397	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
398	    @Override
399	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
400	        Owner owner = this.clinicService.findOwnerById(ownerId);
401	        if (owner != null) {
402	            Pet pet = owner.getPet(petId);
403	            if (pet != null) {
404	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
405	            }
406	        }
407	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
408	    }
409	}
